import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(14))
G.add_edges_from([(9,13), (4,13)])
while True:
    try:
        nx.find_cycle(G)
        break
    except nx.NetworkXNoCycle:
        for u in range(14):
            for v in range(u+1, 14):
                if not G.has_edge(u, v):
                    G.add_edge(u, v)
                    try:
                        nx.find_cycle(G)
                        G.remove_edge(u, v)
                    except nx.NetworkXNoCycle:
                        pass
print("SATISFIABLE")
print(list(G.edges))
